    public void parsePDFStatementForTransactions(ProcessedBankStatementVO processedBankStatementVO) {
        try {
            String fileContent = processedBankStatementVO.processBankStatementCO.textFile.getText("UTF-8")
            if (fileContent.find("Txn[\\s]*No[\\s]*.")) {
                log.debug("========== Extracting transactions from Punjab National bank Current Account Second Type ==========")
                BankTransactionUtil.extractTransactionsFromHTMLHavingDescriptionAboveAndBelowDate(processedBankStatementVO)
            } else if (fileContent.find("Your[\\s]Statement") && fileContent.find("Particulars")) {
                log.debug("========== Extracting transactions from Punjab National Current Account Type 3==========")
                BankTransactionUtil.extractTransactions(processedBankStatementVO)
            } else if ((fileContent.find("Branch\\s*Details") && fileContent.find("Customer\\s*Details") && !fileContent.find("Your[\\s]Statement")) ||
                    (fileContent.find("Account[\\s]*Branch") && fileContent.find("JOINT[\\s]*HOLDERS") && fileContent.find("Statement[\\s]*of[\\s]*account"))) {
                log.debug("========== Extracting transactions from downloaded current account Punjab National bank ==========")
                BankTransactionUtil.extractTransactions(processedBankStatementVO)
            } else {
                log.debug("========== Extracting transactions from Emailed saving account Punjab National bank ==========")
                PnbBankUtil.extractTransactionsFromEmailedSavingAccount(processedBankStatementVO)
            }
        } catch (Exception e) {
            processedBankStatementVO.statementStatus.message = "Error occured during parsing pdf file for PNB statement transactions.  ${e.message}"
            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.ERROR
            log.error(processedBankStatementVO.statementStatus.message, e)
        }
    }
