    public List<CashDepositVO> fetchCashDepositInstances(List<BankTransactionResponse> transactionList) {
        List<CashDepositVO> cashDepositVOList = []
        List<BankTransactionResponse> cashDepositTransactionList = transactionList.findAll {
            (it.transactionCategory == BankTransactionCategory.CASH_DEPOSIT) && (it.isInternalPayment == Boolean.FALSE)
        }
        cashDepositTransactionList = cashDepositTransactionList.sort { it.amount }
        cashDepositTransactionList.each {
            CashDepositVO cashDepositVO = new CashDepositVO(it)
            cashDepositVOList << cashDepositVO
        }
        return cashDepositVOList
    }

    public List<CashDepositVO> fetchCashDepositPerMonth(List<BankTransactionResponse> transactionList) {
        List<CashDepositVO> monthWiseCashDepositVOList = []
        List<CashDepositVO> cashDepositVOList = fetchCashDepositInstances(transactionList).sort { it.date }

        if (cashDepositVOList) {
            List<Date> monthRangeList = DateUtil.getDatesOfMonthsBetweenTwoDates(cashDepositVOList.first().date, cashDepositVOList.last().date)
            monthRangeList.each { Date currentDate ->
                List<CashDepositVO> cashDepositList = cashDepositVOList.findAll {
                    it.date >= DateUtil.getFirstDayOfMonth(currentDate) && it.date <= DateUtil.getLastDayOfMonth(currentDate)
                }
                Long totalCashDepositOfCurrentMonth = cashDepositList*.amount.sum()
                if (totalCashDepositOfCurrentMonth) {
                    monthWiseCashDepositVOList << new CashDepositVO(amount: totalCashDepositOfCurrentMonth, date: DateUtil.getLastDayOfMonth(currentDate), description: "Cash Deposit in ${DateUtil.getLastDayOfMonth(currentDate).format('MMM yyyy')}", total: cashDepositList.size())
                }
            }
        }
        monthWiseCashDepositVOList
    }

    public Double fetchAverageCashDepositPerMonth(List<BankTransactionResponse> transactionList) {
        Double avgCashDeposit = 0.00
        List<CashDepositVO> cashDepositVOList = fetchCashDepositInstances(transactionList)
        if (cashDepositVOList) {
            List<Date> noOfMonths = DateUtil.getDatesOfMonthsBetweenTwoDates(cashDepositVOList.first().date, cashDepositVOList.last().date)
            println "**** No of Months between the date range for Investment : ${noOfMonths.size()}"
            Double totalCashDeposit = cashDepositVOList*.amount.sum()
            avgCashDeposit = totalCashDeposit / noOfMonths.size()
            println " ==== Total Cash Deposit : ${totalCashDeposit} and Monthly Cash Deposit : ${avgCashDeposit}"
        }
        return avgCashDeposit
    }

