    public List<HighValueTransactionVO> fetchHighValueTransactionInstances(List<BankTransactionResponse> transactionList, Integer count = 5) {
        List<HighValueTransactionVO> highValueTransactionVOList = []
        List<BankTransactionResponse> bankTransactionResponseList = transactionList.findAll {
            (it.transactionSubcategory != BankTransactionSubcategory.SALARY && it.transactionCategory != BankTransactionCategory.OPENING_BALANCE)
        }

        count = bankTransactionResponseList.size() < count ? bankTransactionResponseList.size() : count
        List<BankTransactionResponse> highValueTransactionList = bankTransactionResponseList.sort {
            it.amount
        }.reverse().take(count)

        highValueTransactionList.each {
            HighValueTransactionVO highValueTransactionVO = new HighValueTransactionVO(it)
            highValueTransactionVOList << highValueTransactionVO
        }
        return highValueTransactionVOList
    }

    public List<HighValueTransactionVO> fetchHighValueOnTheBasisOfAmount(List<BankTransactionResponse> transactionList, Double amount) {
        List<HighValueTransactionVO> highValueTransactionVOList = []
        transactionList.each { BankTransactionResponse transaction ->
            if (transaction.amount >= amount && !transaction.description.toLowerCase().find("opening\\s*balance")) {
                highValueTransactionVOList.add(new HighValueTransactionVO(transaction))
            }
        }
        return highValueTransactionVOList
    }

