        List<AtmWithdrawlVO> atmWithdrawlVOList = []
        List<BankTransactionResponse> atmWithdrawlTransactionList = transactionList.findAll {
            it.transactionCategory == BankTransactionCategory.ATM_WITHDRAWAL
        }
        atmWithdrawlTransactionList.each {
            AtmWithdrawlVO atmWithdrawlVO = new AtmWithdrawlVO(it)
            atmWithdrawlVOList << atmWithdrawlVO
        }
        return atmWithdrawlVOList
    }

    public List<AtmWithdrawlVO> fetchAtmWithdrawlPerMonth(List<BankTransactionResponse> transactionList) {
        List<AtmWithdrawlVO> monthWiseAtmWithdrawlVOList = []
        List<AtmWithdrawlVO> atmWithdrawlVOList = fetchAtmWithdrawlInstances(transactionList).sort { it.date }
        if (atmWithdrawlVOList) {
            List<Date> monthRangeList = DateUtil.getDatesOfMonthsBetweenTwoDates(atmWithdrawlVOList.first().date, atmWithdrawlVOList.last().date)
