    public List<AverageBalance> calculateAverageQuarterlyBalance(List<BankTransactionResponse> bankTransactionList) {
        List<BankTransactionResponse> quarterlyTransactionList = bankTransactionList.findAll {
            it.isInternalPayment == Boolean.FALSE
        }
        BankTransactionResponse openingBalTransaction = quarterlyTransactionList.first()
        BankTransactionResponse lastTransaction = quarterlyTransactionList.last()
        Calendar calendar = quarterlyTransactionList.size() == 1 ? quarterlyTransactionList.get(0).transactionDate.toCalendar() : quarterlyTransactionList.get(1).transactionDate.toCalendar()
        BigDecimal openingBalance = openingBalTransaction.balanceAfterTransaction
        Integer numOfMonth = Math.ceil(DateUtil.calculateNumberOfMonthsBetweenDateRange(calendar.getTime(), quarterlyTransactionList.last().transactionDate) / 3)
        List<AverageBalance> averageBalanceList = []
        Integer currentEndMonthCount = 2
        (1..numOfMonth).each { monthNum ->
            AverageBalance averageBalance = new AverageBalance()
            Date startDate = DateUtil.getFirstDayOfMonth(calendar.getTime())
            Calendar endCalInstance = calendar
            println("CURRENT MONTH=====>>>>>>   ${currentEndMonthCount + calendar.get(Calendar.MONTH)}           ${monthNum}                      MONTH NUM======>>>>>.   ${calendar.get(Calendar.MONTH)}")
            //TODO:Needs to be configured to consider condition of remaining month lesser than 3
            endCalInstance.add(Calendar.MONTH, currentEndMonthCount)
            Date endDate = DateUtil.getLastDayOfMonth(endCalInstance.getTime())
            println("Start Date===>>>>> ${startDate}                End Date=======>>>>>>>> ${endDate}")
            List<BankTransactionResponse> listTransaction = quarterlyTransactionList.findAll {
                (it.transactionDate.equals(startDate) || it.transactionDate.after(startDate)) && (it.transactionDate.equals(endDate) || it.transactionDate.before(endDate)) && !it.description.equals("OPENING BALANCE")
            }

            Map<Calendar, BigDecimal> monthAnalysisMap = [:]
            (startDate..endDate).each { currentDate ->
                if (!(currentDate.toCalendar().get(Calendar.MONTH) >= lastTransaction.transactionDate.toCalendar().get(Calendar.MONTH) && lastTransaction.transactionDate.before(currentDate))) {
                    List<BankTransactionResponse> transactions = listTransaction.findAll {
                        (it.transactionDate.equals(currentDate) || it.transactionDate.before(currentDate))
                    }
                    if (transactions) {
                        monthAnalysisMap.put(currentDate.toCalendar(), transactions.last().balanceAfterTransaction)
                    } else {
                        List<BankTransactionResponse> transactionsList = listTransaction.findAll {
                            it.transactionDate.after(currentDate)
                        }
                        if (transactionsList) {
                            BankTransactionResponse firstTransaction = transactionsList.first()
                            monthAnalysisMap.put(currentDate.toCalendar(), firstTransaction.type == Enums.BankTransactionType.DEBIT ?
                                    firstTransaction.balanceAfterTransaction + firstTransaction.amount : firstTransaction.balanceAfterTransaction - firstTransaction.amount)
                        } else {
                            monthAnalysisMap.put(currentDate.toCalendar(), 0.0)
                        }
                    }
                }
            }
            BigDecimal quartlySum = 0
            monthAnalysisMap.each { key, value ->
                quartlySum = quartlySum + value
            }
            def groupByDateTransactionMap = listTransaction.groupBy { it.transactionDate }
            Integer numOfDaysOfTransaction = groupByDateTransactionMap.size()
            println("Days==>>>${numOfDaysOfTransaction}   Count of transactions   ============>>>>>>>>>>>>>>             ${listTransaction.size()}")
            SimpleDateFormat dateFormat = new SimpleDateFormat("MMM yyyy")
            if (monthNum == numOfMonth) {
                averageBalance.monthAndYear = dateFormat.format(startDate) + " - " + dateFormat.format(lastTransaction.transactionDate)
            } else {
                averageBalance.monthAndYear = dateFormat.format(startDate) + " - " + dateFormat.format(endDate)
            }
            averageBalance.monthlyBalance = quartlySum ? HelperMethod.roundTo2Places(quartlySum / monthAnalysisMap.size()) : 0.0
            if (averageBalance.monthlyBalance) {
                averageBalanceList << averageBalance
            }
            calendar.set(Calendar.MONTH, calendar.get(Calendar.MONTH) + 1)
        }
        averageBalanceList
    }

