    public List<AverageBalance> calculateAverageMonthlyBalance(List<BankTransactionResponse> bankTransactionList) {
        List<BankTransactionResponse> averageMonthlyBalanceList = bankTransactionList.findAll {
            it.isInternalPayment == Boolean.FALSE
        }
        BankTransactionResponse openingBalTransaction = averageMonthlyBalanceList.first()
        BankTransactionResponse lastTransaction = averageMonthlyBalanceList.last()
        Date endTransactionDate = lastTransaction.transactionDate
        Calendar calendar = averageMonthlyBalanceList.size() == 1 ? averageMonthlyBalanceList.get(0).transactionDate.toCalendar() :
                averageMonthlyBalanceList.get(1).transactionDate.toCalendar()
        BigDecimal openingBalance = openingBalTransaction.balanceAfterTransaction
        Integer numOfMonth = DateUtil.calculateNumberOfMonthsBetweenDateRange(calendar.getTime(), endTransactionDate)
        List<AverageBalance> averageBalanceList = []
        (1..numOfMonth).each { monthNum ->
            Integer numberOfDaysForOverdrawn = 0
            AverageBalance averageBalance = new AverageBalance()
            Date startDate = DateUtil.getFirstDayOfMonth(calendar.getTime())
            Date endDate = DateUtil.getLastDayOfMonth(calendar.getTime())
            List<BankTransactionResponse> listTransaction = averageMonthlyBalanceList.findAll {
                (it.transactionDate.equals(startDate) || it.transactionDate.after(startDate)) &&
                        (it.transactionDate.equals(endDate) || it.transactionDate.before(endDate))
            }
            int lastDate = endDate.toCalendar().get(Calendar.DAY_OF_MONTH)
            Map<Integer, BigDecimal> monthAnalysisMap = [:]
            (startDate..endDate).each { currentDate ->
                if (currentDate.toCalendar().get(Calendar.MONTH) == endTransactionDate.toCalendar().get(Calendar.MONTH) &&
                        endTransactionDate.before(currentDate)) {
                    monthAnalysisMap.put(currentDate.toCalendar().get(Calendar.DAY_OF_MONTH), -1)
                } else {
                    List<BankTransactionResponse> transactions = listTransaction.findAll {
                        (it.transactionDate.equals(currentDate) || it.transactionDate.before(currentDate))
                    }
                    if (transactions) {
                        monthAnalysisMap.put(currentDate.toCalendar().get(Calendar.DAY_OF_MONTH), transactions.last().balanceAfterTransaction)
                    } else {
                        List<BankTransactionResponse> transactionList = listTransaction.findAll {
                            it.transactionDate.after(currentDate)
                        }
                        if (transactionList) {
                            BankTransactionResponse firstTransaction = transactionList.first()
                            monthAnalysisMap.put(currentDate.toCalendar().get(Calendar.DAY_OF_MONTH), firstTransaction.type == Enums.BankTransactionType.DEBIT ?
                                    firstTransaction.balanceAfterTransaction + firstTransaction.amount : firstTransaction.balanceAfterTransaction - firstTransaction.amount)
                        } else {
                            monthAnalysisMap.put(currentDate.toCalendar().get(Calendar.DAY_OF_MONTH), 0.0)
                        }
                    }
                }
            }

            def groupByDateTransactionMap = listTransaction.groupBy { it.transactionDate }
            Calendar currentCalInstance = startDate.toCalendar()
            Integer numOfDaysOfTransaction = groupByDateTransactionMap.size()
            calendar.add(Calendar.MONTH, 1)
            SimpleDateFormat dateFormat = new SimpleDateFormat("MMM yyyy")
            averageBalance.monthAndYear = dateFormat.format(currentCalInstance.getTime())
            BigDecimal totalMonthlyBalance = listTransaction*.balanceAfterTransaction.sum() as BigDecimal
            if (monthNum == 1) {
                totalMonthlyBalance += openingBalance
                lastDate = lastDate - openingBalTransaction.transactionDate.toCalendar().get(Calendar.DAY_OF_MONTH) + 1
            }
            Map<Integer, BigDecimal> dayAnalysisMap = [:]
            def key1 = monthAnalysisMap.keySet().toArray()[0]
            def value1 = monthAnalysisMap.get(key1)
            dayAnalysisMap.put(1, (value1))
            BigDecimal monthlyBalance = 0
            Calendar dayAnalysisCal = Calendar.getInstance()
            (1..6).each { numDay ->
                dayAnalysisCal.set(Calendar.DAY_OF_MONTH, numDay * 5)
                monthlyBalance = 0
                numberOfDaysForOverdrawn = 0
                monthAnalysisMap.each { key, value ->
                    if (dayAnalysisCal.get(Calendar.DAY_OF_MONTH) == key) {
                        dayAnalysisMap.put(dayAnalysisCal.get(Calendar.DAY_OF_MONTH), value)
                    }
                    monthlyBalance = monthlyBalance + value

                    //============================FOR OVERDRAWN=============================
                    if (value < -1) {
                        numberOfDaysForOverdrawn += 1
                    }
                }
            }
//            if (dayAnalysisMap.size() < 7) {
//                dayAnalysisCal.set(Calendar.DAY_OF_MONTH, 30)
//                dayAnalysisMap.put(dayAnalysisCal.get(Calendar.DAY_OF_MONTH), -1)
//            }
            averageBalance.dayAmountMap = dayAnalysisMap
            Date date = lastTransaction.transactionDate
            int lastTranscationDate = date.toCalendar().get(Calendar.DAY_OF_MONTH);
            if (totalMonthlyBalance && monthlyBalance) {
                averageBalance.amount = HelperMethod.roundTo2Places(totalMonthlyBalance / numOfDaysOfTransaction)

                if (startDate.toCalendar().get(Calendar.MONTH) == date.toCalendar().get(Calendar.MONTH) && startDate.toCalendar().get(Calendar.YEAR) == date.toCalendar().get(Calendar.YEAR)) {
                    averageBalance.monthlyBalance = HelperMethod.roundTo2Places(monthlyBalance / lastTranscationDate)
                } else {
                    averageBalance.monthlyBalance = HelperMethod.roundTo2Places(monthlyBalance / lastDate)
                }

            } else {
                averageBalance.amount = 0
                averageBalance.monthlyBalance = 0
            }
            averageBalance.numberOfOverdrawnDays = numberOfDaysForOverdrawn
            if (listTransaction) {
                averageBalanceList << averageBalance
            }
        }
        averageBalanceList
    }

