    public List<LoanRepaymentVO> fetchLoanPaymentPerMonth(List<BankTransactionResponse> bankTransactionList) {
        List<LoanRepaymentVO> monthWiseLoanPaymentList = []
        List<LoanRepaymentVO> loanRepaymentVOList = calculatLoanPaymentAnalysis(bankTransactionList)
        List<Date> monthRangeList = DateUtil.getDatesOfMonthsBetweenTwoDates(bankTransactionList.first().transactionDate, bankTransactionList.last().transactionDate)
        monthRangeList.each { Date currentDate ->
            List<LoanRepaymentVO> loanRepayments = loanRepaymentVOList.findAll {
                it.dateTime >= DateUtil.getFirstDayOfMonth(currentDate) && it.dateTime <= DateUtil.getLastDayOfMonth(currentDate)
            }
            Double debitAmount = 0
            Double creditAmount = 0
            Integer totalCredit = 0
            Integer totalDebit = 0
            if (loanRepayments) {
                loanRepayments.each { loanRepayment ->
                    if (loanRepayment.transactionType == Enums.BankTransactionType.DEBIT as String) {
                        debitAmount = debitAmount + loanRepayment.amount
                        totalDebit = totalDebit + 1
                    } else {
                        creditAmount = creditAmount + loanRepayment.amount
                        totalCredit = totalCredit + 1
                    }
