    public BankAccount saveBankStmtAccount(ProcessedBankStatementVO processedBankStatementVO, Client client = null) {
        ProcessBankStatementCO processBankStatementCO = processedBankStatementVO?.processBankStatementCO
        client = client ?: processBankStatementCO.client
        Customer customer = null
        String bank = processBankStatementCO ? processBankStatementCO.bank : processedBankStatementVO.bankCredentialCO.bank
        if (!customer) {
            String customerEmailAddress = bank + "_" + processedBankStatementVO.basicDetails.accountNumber
            log.debug("CLient=================>>>>>>>>>>>>>>>>>                   ${client}")
            customer = Customer.findOrCreateByEmailAddressAndClient(customerEmailAddress, client)
            AppUtil.save(customer)
        }
        BankAccount bankAccount = BankAccount.findByAccountNoAndCustomerUIDAndBank(EncryptDecrypt.encrypt(processedBankStatementVO.accountNumber), customer?.uniqueId, Enums.Bank.valueOf(bank))
        if (Enums.Bank.valueOf(bank) in [Enums.Bank.SOUTH_INDIAN] ? !(bankAccount && bankAccount.getDecryptedAccountName().replaceAll(" ", "").trim().equalsIgnoreCase(processedBankStatementVO.accountHolder.replaceAll(" ", "").trim())) : !bankAccount) {
            log.info("***********************          New Bank Account Created             ***********************")
            bankAccount = new BankAccount(processedBankStatementVO, customer, bank)
            Map<String, String> parseMessage = processedBankStatementVO.statementStatus ? processedBankStatementVO.statementStatus.parseMessage : [:]
            bankAccount.parseMessage = updateParseMessage(parseMessage, bankAccount)
            AppUtil.save(bankAccount)
            if (processBankStatementCO && processBankStatementCO.parsingType != Enums.StatementParsingType.REFRESH) {
                log.info("***********************          Creating Bank Statement Object             ***********************")
                processedBankStatementVO.requestQueueList.each { RequestQueue requestQueue ->
                    BankStatement bankStatement = new BankStatement(processedBankStatementVO, requestQueue.document, bankAccount)
                    AppUtil.save(bankStatement)
                }
            }
        } else {
            log.info("***********************          Existing Bank Account Found             ***********************")
            bankAccount.accountType = processedBankStatementVO.processBankStatementCO ? Enums.AccountType.valueOf(processedBankStatementVO.processBankStatementCO.accountType) : Enums.AccountType.SAVING
            bankAccount.parseMessage = updateParseMessage(processedBankStatementVO.statementStatus.parseMessage, bankAccount)
            AppUtil.save(bankAccount)
            if (processBankStatementCO && processBankStatementCO.parsingType != Enums.StatementParsingType.REFRESH) {
                log.info("***********************          Creating Bank Statement Object             ***********************")
                processedBankStatementVO.requestQueueList.each { RequestQueue requestQueue ->
                    BankStatement bankStatement = new BankStatement(processedBankStatementVO, requestQueue.document, bankAccount)
                    AppUtil.save(bankStatement)
                }
            }
        }
        if (processBankStatementCO)
            updateBankAccountComponentAssociation(bankAccount, processBankStatementCO)
        String employerDetails = processBankStatementCO?.employerDetails
        if (employerDetails && StringUtils.isNotBlank(employerDetails))
            bankAccount.salaryKeyword =<REDACTED>
        if (processBankStatementCO?.oDLimit)
            bankAccount.accountLimit = BigDecimal.valueOf(Double.valueOf(processBankStatementCO.oDLimit))
        if (AppUtil.save(bankAccount) && processBankStatementCO?.parsingType != Enums.StatementParsingType.REFRESH) {
            String selectedBankAccountUID = processBankStatementCO ? processBankStatementCO?.accountUID : processedBankStatementVO.bankCredentialCO.accountUID
            bankService.handleCustomerAccountMapping(selectedBankAccountUID, bankAccount)
        }
        bankAccount
    }

    public void updateBankAccountComponentAssociation(BankAccount bankAccount, ProcessBankStatementCO processBankStatementCO) {
        String newBankAccountUID = processBankStatementCO.uniqueId
        if (!bankAccount.accountUIDList)
            bankAccount.accountUIDList = []
        List<BankStatement> bankStatementList = BankStatement.findAllByBankAccountUID(bankAccount.uniqueId)
        bankStatementList*.bankAccountUID = newBankAccountUID
        bankStatementList*.save(flush: true)

        List<RequestQueue> requestQueueList = RequestQueue.findAllByAccountUID(bankAccount.uniqueId)
        requestQueueList*.accountUID = newBankAccountUID
        requestQueueList*.save(flush: true)

        if (bankAccount.bankTransactionData)
            bankAccount.bankTransactionData = bankAccount.bankTransactionData.replaceAll(bankAccount.uniqueId, newBankAccountUID)
        bankAccount.uniqueId = newBankAccountUID
        if (processBankStatementCO.accountUIDList)
            bankAccount.accountUIDList.addAll(processBankStatementCO.accountUIDList)
        if (!(newBankAccountUID in bankAccount.accountUIDList))
            bankAccount.accountUIDList.add(newBankAccountUID)

    }

    public void saveTransactions(ProcessedBankStatementVO processedBankStatementVO, BankAccount bankAccount) {
        String bank = processedBankStatementVO?.processBankStatementCO ? processedBankStatementVO?.processBankStatementCO?.bank : processedBankStatementVO.bankCredentialCO.bank
        List<BankTransactionResponse> bankTransactionResponseList = bankAccount?.bankTransactionResponseList ?: []
        List<BankTransactionResponse> newBankTransactionResponseList = []
        BankTransactionResponse existingOpeningTransaction = bankTransactionResponseList.find {
            it.description.equals("OPENING BALANCE")
        }
        log.debug "====######## Existing Opening Balance Transaction ###### ======== : ${existingOpeningTransaction?.balanceAfterTransaction}"
        log.debug("^^^^^^^^^^^^^^^^^^^^^^^                New Opening Transaction Date ==========>>>>>>>>>>>>>    " +
                "${processedBankStatementVO.basicDetails.fromDate?.getTime()?.clearTime()}")
        BankTransactionResponse bankTransactionResponse = null
        bankTransactionResponse = processedBankStatementVO.bankTransactionList.find {
            it.description.equals("OPENING BALANCE")
        }
        processedBankStatementVO.bankTransactionList.remove(bankTransactionResponse)
        if ((!existingOpeningTransaction || existingOpeningTransaction.transactionDate.after(processedBankStatementVO.basicDetails.fromDate?.getTime()?.clearTime())) && bankTransactionResponse) {
            if (existingOpeningTransaction)
                bankTransactionResponseList.remove(existingOpeningTransaction)
            log.debug("***********            Amount  ===>>>> ${bankTransactionResponse.amount}               Balance ======>>>>> ${bankTransactionResponse.balanceAfterTransaction}")
            BankTransactionResponse openingBalanceTransaction = new BankTransactionResponse()
            openingBalanceTransaction.transactionDate = bankTransactionResponse.transactionDate
            openingBalanceTransaction.amount = bankTransactionResponse.balanceAfterTransaction
            openingBalanceTransaction.type = Enums.BankTransactionType.CREDIT
            openingBalanceTransaction.balanceAfterTransaction = bankTransactionResponse.balanceAfterTransaction
            openingBalanceTransaction.description = "OPENING BALANCE"
            openingBalanceTransaction.transactionCategory = BankTransactionCategory.OPENING_BALANCE
            openingBalanceTransaction.firstLevelTransactionCategoryUID = TransactionCategory.findByName(TransactionCategoryConstant.BankTransactionCategoryConstant.OPENING_BALANCE.value).uniqueId
            openingBalanceTransaction.bankAccountUID = bankAccount.uniqueId
            newBankTransactionResponseList << openingBalanceTransaction
        }
        processedBankStatementVO.bankTransactionList.each { transactionResponse ->
            BankTransactionResponse bankTransaction = bankTransactionResponseList.find {
                transactionResponse?.balanceAfterTransaction == it.balanceAfterTransaction &&
                        transactionResponse?.description == it.description &&
                        transactionResponse?.transactionDate == it.transactionDate
            }

            if (bankTransaction && bankTransaction.amount == 0.0 as Double) {
                bankTransaction.amount = transactionResponse.amount
            } else if (!bankTransaction) {
                transactionResponse.bankAccountUID = bankAccount.uniqueId
                newBankTransactionResponseList << transactionResponse
            }
        }
        log.debug "=== 'Saved Transaction for ${bank} Bank"
        bankTransactionResponseList.addAll(newBankTransactionResponseList)
        log.debug("Transactions to be saved     =============>>>>>>>>>>>>>>         ${bankTransactionResponseList.size()}")
        if (bankAccount.accountType in [Enums.AccountType.OVER_DRAFT, Enums.AccountType.CASH_CREDIT]) {
            BankUtil.calculateEstimatedODLimit(bankTransactionResponseList, bankAccount)
        }
        bankAccount.bankTransactionData = BankUtil.fetchTransactionJsonString(bankTransactionResponseList)
    }

    public def createTransactionMap(def transactionList, List list, String transactionDate) {
        transactionList.each { transaction ->
            def map = [:]
            map.date = transactionDate == "monthAndYear" ? transaction."${transactionDate}" : transaction."${transactionDate}".format('MMM yyyy')
            map.amount = transaction.amount
            map.description = transaction.description
            map.total = transaction.total
            list << map
        }
    }

    public Map<String, String> updateParseMessage(Map<String, String> parseMsgMap, BankAccount bankAccount) {
        parseMsgMap.each { String key, String value ->
            value ? bankAccount?.parseMessage?.put(key, value) : bankAccount?.parseMessage?.remove(key)
        }
        bankAccount.parseMessage
    }

