/**
 * Normalizes a date cell of a statement table so that all the layouts supported by the shared parser end up
 * with a single representation. It takes care of the month name dates which may be separated by spaces,
 * hyphens(or slashes) or which may not have any separator at all. Known OCR errors of month names
 * (like JUY for JUL) are corrected as well.
 */
public static String normalizeDate(String date) {
    if (date == null) {
        return null
    }
    String value = processValue(date.trim()).trim()
    if (!value) {
        return value
    }
    java.util.regex.Matcher matcher = java.util.regex.Pattern.compile(GROUPED_MONTH_NAME_DATE_REGEX).matcher(value)
    if (matcher.matches()) {
        String day = matcher.group(1)
        String month = matcher.group(2).toUpperCase()
        month = MONTH_NAME_CORRECTION_MAP.get(month) ?: month
        month = month.length() > 3 ? month.substring(0, 3) : month
        month = MONTH_NAME_CORRECTION_MAP.get(month) ?: month
        String year = matcher.group(3)
        if (month in MONTH_NAME_LIST) {
            value = "${day.length() == 1 ? '0' + day : day} ${month} ${year}"
        }
    }
    value.trim()
}

/**
 * Parses a date cell of a statement table. Returns null(instead of throwing an exception) when the given
 * value does not hold a date, so that the caller can decide how such a row has to be treated.
 */
public static Date parseDate(String date) {
    String value = normalizeDate(date)
    if (!value) {
        return null
    }
    SimpleDateFormat dateFormat = dateFormatFromString(value)
    if (!dateFormat) {
        return null
    }
    try {
        return dateFormat.parse(value)
    } catch (Exception e) {
        return null
    }
}

public static Date parseDate(String date, String dateFormatPattern) {
    if (dateFormatPattern) {
        try {
            return new SimpleDateFormat(dateFormatPattern).parse(normalizeDate(date))
        } catch (Exception e) {
        }
    }
    parseDate(date)
}

public static String cellText(Element element, Integer index) {
    (element != null && index != null) ? element.select("td").eq(index).text() : ""
}

public static Boolean isCompleteAmount(String value) {
    value && value.trim().find(COMPLETE_AMOUNT_REGEX) ? Boolean.TRUE : Boolean.FALSE
}

/**
 * Statements spanning over multiple pages repeat their transaction table header. Such a row does not hold a
 * date but holds the column names hence it has to be skipped instead of being reported as a parsing failure.
 */
public static Boolean isTransactionHeaderRow(Element element, BankTransactionHeaderIndex bankTransactionHeaderIndex) {
    Map<String, String> headerMap = headerDictionary()
    String date = cellText(element, bankTransactionHeaderIndex.transactionDateIndex).trim()
    String description = cellText(element, bankTransactionHeaderIndex.descriptionIndex).trim()
    String balance = cellText(element, bankTransactionHeaderIndex.balanceAfterTransactionIndex).trim()
    if (parseDate(date) || !element?.text()?.trim()) {
        return Boolean.FALSE
    }
    Integer matchedHeaderCount = 0
    if (date && date.find(headerMap.date)) {
        matchedHeaderCount++
    }
    if (description && description.find(headerMap.description)) {
        matchedHeaderCount++
    }
    if (balance && balance.find(headerMap.balance_after_transaction)) {
        matchedHeaderCount++
    }
    if (cellText(element, bankTransactionHeaderIndex.valueDateIndex).trim().find(headerMap.value_date)) {
        matchedHeaderCount++
    }
    matchedHeaderCount >= 2
}

public static Boolean isJunkRow(Element element, BankTransactionHeaderIndex bankTransactionHeaderIndex) {
    Map<String, String> headerMap = headerDictionary()
    String date = cellText(element, bankTransactionHeaderIndex.transactionDateIndex).trim()
    String description = cellText(element, bankTransactionHeaderIndex.descriptionIndex).trim()
    (date.find(headerMap.junk_date) || description.find(headerMap.junk_date)) ? Boolean.TRUE : Boolean.FALSE
}

/**
 * Recognizes the balance brought forward(opening balance) row of a statement table.
 */
public static Boolean isOpeningBalanceRow(Element element, BankTransactionHeaderIndex bankTransactionHeaderIndex) {
    Map<String, String> headerMap = headerDictionary()
    String description = cellText(element, bankTransactionHeaderIndex.descriptionIndex).trim()
    String date = cellText(element, bankTransactionHeaderIndex.transactionDateIndex).trim()
    (description.find(headerMap.balance_brought_forward) || (!parseDate(date) && date.find(headerMap.balance_brought_forward))) ?
            Boolean.TRUE : Boolean.FALSE
}

/**
 * Assigns the amount along with its direction(debit or credit) to the transaction. Handles all the column
 * combinations used by the supported layouts i.e. separate debit and credit columns, a single amount column
 * and a single amount column accompanied by a debit/credit indicator column.
 */
public static void assignAmountAndType(Element element, BankTransactionHeaderIndex bankTransactionHeaderIndex,
                                       BankTransactionResponse bankTransactionResponse) {
    String debit = bankTransactionHeaderIndex.debitIndex != null ? cellText(element, bankTransactionHeaderIndex.debitIndex) : null
    String credit = bankTransactionHeaderIndex.creditIndex != null ? cellText(element, bankTransactionHeaderIndex.creditIndex) : null
    String amount = bankTransactionHeaderIndex.amountIndex != null ? cellText(element, bankTransactionHeaderIndex.amountIndex) : null
    String amountType = bankTransactionHeaderIndex.amountTypeIndex != null ? cellText(element, bankTransactionHeaderIndex.amountTypeIndex) : null
    if (debit && !debit.find("^[\\s]*(-[\\s]*)?\$")) {
        bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(debit)
        bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
    }
    if (credit && !credit.find("^[\\s]*(-[\\s]*)?\$") && (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
        bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(credit)
        bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
    }
    if (amount) {
        bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(amount)
        if (!bankTransactionResponse.type) {
            bankTransactionResponse.type = amount.toLowerCase().find("dr") ? Enums.BankTransactionType.DEBIT :
                    (amount.toLowerCase().find("cr") ? Enums.BankTransactionType.CREDIT : bankTransactionResponse.type)
        }
    }
    if (amountType) {
        if (amountType.toLowerCase().find("cr"))
            bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
        else
            bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
    }
}

